map "http://example.org/fhir/concatenation/StructureMap/Visit" = `Visit`

uses "http://example.org/fhir/concatenation/StructureDefinition/VisitRow" alias VisitRow as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target
uses "http://hl7.org/fhir/StructureDefinition/Observation" alias Observation as target

// Main group: one transaction Bundle per normalized record.
// Each role becomes an entry with PUT on its deterministic id (computed by the normalization).
group Visit(source src : VisitRow, target bundle : Bundle) {
  src -> bundle.type = 'transaction' "bundle-type";
  // Patient[0] · patient — always
  src where ($this.id_Patient0.exists()) -> bundle.entry as e, e.resource = create('Patient') as res, e.request as req then {
    src.id_Patient0 as i -> res.id = i, req.method = 'PUT', req.url = evaluate(i, 'Patient/' + $this), e.fullUrl = evaluate(i, 'http://example.org/fhir/concatenation/Patient/' + $this) "Patient0-id";
    src then Patient0(src, res) "Patient0-body";
  } "Patient0";
  // Observation[0] · note — always
  src where ($this.id_Observation0.exists()) -> bundle.entry as e, e.resource = create('Observation') as res, e.request as req then {
    src.id_Observation0 as i -> res.id = i, req.method = 'PUT', req.url = evaluate(i, 'Observation/' + $this), e.fullUrl = evaluate(i, 'http://example.org/fhir/concatenation/Observation/' + $this) "Observation0-id";
    src then Observation0(src, res) "Observation0-body";
  } "Observation0";
}

group Patient0(source src : VisitRow, target res : Patient) {
  src.patient_id as v -> res.identifier as p, p.value = v "R-001";
  // name: written by 2 rows (R-002, R-003) → one shared instance
  src where ($this.title.exists() or $this.given.exists() or $this.family.exists()) -> res.name as p then {
    src where ($this.title.exists() or $this.given.exists() or $this.family.exists()) -> p.text = evaluate(src, $this.title.toString().combine($this.given.toString()).combine($this.family.toString()).join(' ')) "R-002";
    src.family as v -> p.family = v "R-003";
  } "Patient0-name";
}

group Observation0(source src : VisitRow, target res : Observation) {
  src -> res.status = 'final' "fixed-status";
  src -> res.code = cc('http://loinc.org', '48767-8', 'Annotation comment [Interpretation] Narrative') "fixed-code";
  src where ($this.systolic.exists() or $this.diastolic.exists()) -> res.value = evaluate(src, $this.systolic.toString().combine($this.diastolic.toString()).join('/')) "R-004";
  src where ($this.score.exists() or $this.comment.exists()) -> res.note as p, p.text = evaluate(src, $this.score.toString().combine($this.comment.toString()).join('JyDCtyAn'.decode('base64'))) "R-005";
  src.id_Patient0 as t -> res.subject as r, r.reference = evaluate(t, 'Patient/' + $this) "R-006";
}
